import pytest


def test_generated():
    from sympy import Poly, symbols, ZZ
    from sympy.polys.polyclasses import DMP
    x, y = symbols('x y')

    def outcome(f):
        try:
            return str(f())
        except Exception as exc:
            return 'raised ' + type(exc).__name__
    assert repr([outcome(lambda: Poly(x**2 + 2*x + 3).nth(0.5)), outcome(lambda: Poly(x*y + 1, x, y).nth(1, 1)), outcome(lambda: Poly(x + 1).nth(-1))]) == "['raised TypeError', '1', 'raised IndexError']"

